{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection",
      "severity": "Medium",
      "file": "TaskSearchController.cls",
      "lines": "8",
      "explanation": "The subjectFilter input is concatenated into a dynamic SOQL string without using bind variables, risking SOQL injection.",
      "remediation": "Use bind variables or Database.queryWithBinds to safely include user input in SOQL queries."
    },
    {
      "category": "C2",
      "title": "CRUD/FLS Violation",
      "severity": "Medium",
      "file": "TaskSearchController.cls",
      "lines": "8",
      "explanation": "The query does not enforce field-level security (FLS) by using WITH SECURITY_ENFORCED.",
      "remediation": "Change the query to use WITH SECURITY_ENFORCED to enforce field-level security."
    }
  ]
}

